def solve_small_n(n):
    inv2 = pow(2, -1, n)
    possible_sizes = set()
    for i in range(1, 1 << n):
        K = [j for j in range(n) if (i >> j) & 1]
        if len(K) < 3:
            continue

        is_valid = True
        for p in K:
            for q in K:
                r = (p + q) * inv2 % n
                if r not in K:
                    is_valid = False
                    break
            if not is_valid:
                break

        if is_valid:
            possible_sizes.add(len(K))
    return sorted(list(possible_sizes))

